 for j := 2 to round(sqrt(i)) do begin
 if i mod j = 0 then
 if j mod 2 = 0 then count := count + 1;
 if i mod j = 0 then
 if (i div j) mod 2 = 0 then count := count + 1;
 if (j * j = i) and (j mod 2 = 0) then count := count - 1;
 if count > 3 then break;
 end;
 end;
 if count = 3 then writeln(i);
 count := 1;
 end;
end.
