def f(x):
 # Находим все натуральные делители, не считая 1 и x
 divs = []
 for i in range(2, int(x**0.5)+1):
 if x % i == 0:
 divs.append(i)
 if i != x // i:
 divs.append(x // i)
 # Находим уникальные простые делители (не считая самого x)
 primes = []
 temp = x
 d = 2
 while d * d 1 and temp != x:
 primes.append(temp)
